const LAST=TUTORIAL_STEPS.length-1;
export function createTutorial({storage,requestLocation,onChange=()=>{},onFinish=()=>{}}={}){
 let index=0,active=false,busy=false,replay=false,status='',remembered=true;
 function saved(){try{const value=JSON.parse(storage?.getItem(TUTORIAL_KEY)??'null');return value?.version===1?value:null;}catch{return null;}}
 function persist(completed=false){try{if(!storage?.setItem)throw Error();storage.setItem(TUTORIAL_KEY,JSON.stringify({version:1,completed,step:index}));remembered=true;}catch{remembered=false;}}
 const state=()=>({index,step:TUTORIAL_STEPS[index],total:TUTORIAL_STEPS.length,active,busy,replay,status,remembered});
 const emit=()=>onChange(state());
 function go(next){if(!active||busy||!Number.isInteger(next))return;index=Math.min(LAST,Math.max(0,next));status='';if(!replay)persist();emit();}
 function finish(){persist(true);active=false;emit();onFinish();}
 return {
  state,
  start({replay:again=false,chapter}={}){if(active)return false;const previous=saved();if(!again&&previous?.completed===true)return false;replay=again;index=chapter==='location'?LAST:again?0:Number.isInteger(previous?.step)&&previous.step>=0&&previous.step<=LAST?previous.step:0;active=true;busy=false;status='';emit();return true;},
  go,next(){go(index+1);},back(){go(index-1);},
  skip(){if(!active||busy)return;if(index===LAST||replay)finish();else go(LAST);},
  continueWithoutLocation(){if(active&&!busy)finish();},
  async allowLocation(){if(!active||busy||index!==LAST)return;busy=true;status='Opening location access…';emit();try{const result=await requestLocation();if(result?.state==='granted'){busy=false;finish();return;}status=result?.state==='denied'?'Location was not allowed. You can continue and enable it later in device settings.':'Location is unavailable here. Continue using a town, street or a chosen map point.';}catch(error){status=error.message||'Location access could not open. You can continue without it.';}finally{busy=false;emit();}}
  ,reset(){active=false;busy=false;},canClose(){if(!active)return true;if(busy)return false;if(index>0){go(index-1);return false;}if(replay){persist(true);active=false;emit();return true;}go(LAST);return false;}
 };
}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createTutorialUI({document,storage,requestLocation,show,close,icon=()=>'',onStatus=()=>{}}){
 const $=id=>document.getElementById(id);
 function render(s){const page=s.step,final=page.id==='location';$('tutorial-eyebrow').textContent=page.eyebrow;$('tutorial-title').textContent=page.title;$('tutorial-path').textContent=page.path;$('tutorial-intro').textContent=page.intro;$('tutorial-hint').textContent=page.hint;$('tutorial-count').textContent=`${s.index+1} / ${s.total}`;$('tutorial-progress').max=s.total;$('tutorial-progress').value=s.index+1;$('tutorial-chapter').value=String(s.index);$('tutorial-preview').innerHTML=`<span class="guide-stamp">${icon(page.icon)}</span><div>${page.preview.map(label=>`<span>${esc(label)}</span>`).join('')}</div>`;$('tutorial-steps').innerHTML=page.steps.map(([title,body],i)=>`<li><span class="guide-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(title)}</h3><p>${esc(body)}</p></div></li>`).join('');$('tutorial-back').hidden=s.index===0;$('tutorial-next').hidden=final;$('tutorial-next').textContent=s.index===0?'Show me around':s.index===s.total-2?'Set up location':'Next chapter';$('tutorial-allow').hidden=!final||!!s.status&&!s.busy;$('tutorial-allow').disabled=s.busy;$('tutorial-finish').hidden=!final;$('tutorial-finish').disabled=s.busy;$('tutorial-finish').textContent=s.status&&!s.busy?'Open my journal':'Continue without location';$('tutorial-retry').hidden=!final||!s.status||s.busy;$('tutorial-status').textContent=s.status;$('tutorial-remember').textContent=s.remembered?'':'This device could not remember tutorial progress. The guide may appear again on your next launch.';$('tutorial-skip').textContent=s.replay?'Close guide':final?'Continue without location':'Skip to location setup';for(const id of ['tutorial-back','tutorial-next','tutorial-chapter','tutorial-skip'])$(id).disabled=s.busy;$('tutorial').setAttribute('aria-busy',String(s.busy));}
 const controller=createTutorial({storage,requestLocation,onChange:render,onFinish:()=>close('tutorial',{force:true})});
 const move=fn=>{fn();if(controller.state().active){$('tutorial').scrollTop=0;$('tutorial-title').focus({preventScroll:true});}};
 return {
  start(options){if(controller.start(options)){show('tutorial');return true;}return false;},
  wire(){$('tutorial-chapter').innerHTML=TUTORIAL_STEPS.map((s,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${esc(s.id==='location'?'Location setup':s.title)}</option>`).join('');$('tutorial-chapter').onchange=e=>move(()=>controller.go(Number(e.target.value)));$('tutorial-next').onclick=()=>move(()=>controller.next());$('tutorial-back').onclick=()=>move(()=>controller.back());$('tutorial-skip').onclick=()=>move(()=>controller.skip());$('tutorial-finish').onclick=()=>controller.continueWithoutLocation();$('tutorial-allow').onclick=()=>void controller.allowLocation();$('tutorial-retry').onclick=()=>void controller.allowLocation();},
  reset(){controller.reset();},
  canClose(){const allowed=controller.canClose();if(controller.state().busy)onStatus('Finish the system permission choice before closing the guide.');return allowed;},
  get active(){return controller.state().active;}
 };
}
